import fsExtra from "fs-extra";
import { getObjectHash } from "./crypto";
import { IFileItem } from "./types";

export interface IManifest {
  name: string;
  version: string;
  basis: string;
  files: Array<IFileItem & { vc: string }>;
  vc: string;
}

export interface IGameConfig {
  tag: string;
  version: string;
  name: string;
  params?: string[];
}

export function readManifestFile(manifestPath: string) {
  const data = fsExtra.readJSONSync(manifestPath, {
    throws: false,
    encoding: "utf-8",
  }) as IManifest;

  const result = { ...data };
  delete (result as any).vc;
  delete (result as any).files;
  const infoVC = data?.vc;
  const checkVC = getObjectHash(result);
  if (infoVC !== checkVC) {
    for (const key in result) {
      result[key] = "";
    }
  }

  const validFiles =
    data?.files?.filter((item) => {
      const itemData = { ...item };
      delete (itemData as any).vc;
      const checkVC = getObjectHash(itemData);
      return item.vc === checkVC;
    }) || [];

  return { ...result, vc: data?.vc, files: validFiles };
}
// 读取配置
export const readGameConfigFile = (gameConfigPath: string): IGameConfig => {
  const origin: any = {};
  try {
    const data = fsExtra.readFileSync(gameConfigPath, { encoding: "utf-8" });
    Object.assign(origin, JSON.parse(data));
  } catch (err) {
    return {} as any;
  }
  const vc = origin.vc;
  delete origin.vc;
  const newVc = getObjectHash(origin);
  if (vc !== newVc) {
    fsExtra.remove(gameConfigPath, (err) => {
      if (err) {
        // Logger.warn('game config error', `error config:\n${JSON.stringify(origin)}`);
      }
    });
    return {} as any;
  }
  return origin;
};

export const getDownloadTmpName = (name: string) => `${name}.tmp`;
export const getDownloadOriginName = (tmpName: string) => tmpName.replace(/\.tmp$/, "");
